const STATUS_FRACTION = { met: 1.0, partial: 0.5, missing: 0.0 };
const REQUIRED_WEIGHT = 2;
const OPTIONAL_WEIGHT = 1;
const COVERAGE_FLOOR = 0.5;
const T_ADVANCE = 50;
const T_CONSIDER = 30;
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }
function txt(v) { return String(v == null ? '' : v).trim(); }
function toArray(v) { if (Array.isArray(v)) return v.filter((x) => txt(x)); const s = txt(v); return s ? [s] : []; }
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }
function getAssessment(item) { const j = item.json || {}; if (j.output && typeof j.output === 'object') return j.output; if (j.criteria || j.integrity_concerns) return j; const raw = j.text || j.response || j.data || ''; const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch (e) {} } return {}; }
function getContext(item) { let body = {}; try { body = $('Webhook').first().json.body || {}; } catch (e) { body = (item.json && item.json.__body) || {}; } const rawCriteria = Array.isArray(body.criteria) ? body.criteria : []; const def = {}; rawCriteria.forEach((c, i) => { const id = txt(c && c.id) || ('c' + (i + 1)); def[id] = { text: txt(c && (c.text != null ? c.text : c)), required: (c && c.required) === true }; }); return { def, body, screening: body.screening || {} }; }
const out = [];
for (const item of $input.all()) {
  const a = getAssessment(item);
  const ctx = getContext(item); const def = ctx.def; const body = ctx.body; const screening = ctx.screening;
  const items = Array.isArray(a.criteria) ? a.criteria : [];
  let totalWeight = 0, assessedWeight = 0, earned = 0;
  const requiredMissing = [];
  const criteriaResults = [];
  for (const id of Object.keys(def)) totalWeight += def[id].required ? REQUIRED_WEIGHT : OPTIONAL_WEIGHT;
  for (const c of items) {
    const id = txt(c && (c.criterionId != null ? c.criterionId : c.id));
    const d = def[id]; if (!id || !d) continue;
    const w = d.required ? REQUIRED_WEIGHT : OPTIONAL_WEIGHT;
    const st = norm(c.status);
    if (st === 'not_assessed' || st === 'not assessed' || !(st in STATUS_FRACTION)) { criteriaResults.push({ criterionId: id, status: 'not_assessed', required: d.required }); continue; }
    if (st === 'missing' && d.required) requiredMissing.push(id);
    earned += STATUS_FRACTION[st] * w;
    assessedWeight += w;
    criteriaResults.push({ criterionId: id, status: st, required: d.required, evidence: txt(c.evidence) });
  }
  const flags = [];
  const candSalaryMin = num(body.salaryMin);
  const budgetMax = num(screening.budgetMax);
  if (candSalaryMin !== null && budgetMax !== null && candSalaryMin > budgetMax) { flags.push('salary_above_budget'); }
  const reqLoc = norm(screening.requiredLocation);
  const candLoc = norm(body.location);
  const relocation = body.willingToRelocate === true || screening.remoteOk === true;
  if (reqLoc && candLoc && !candLoc.includes(reqLoc) && !reqLoc.includes(candLoc) && !relocation) { flags.push('location_mismatch'); }
  const integrity = (Array.isArray(a.integrity_concerns) ? a.integrity_concerns : []).filter((c) => txt(c && c.concern) && txt(c && c.quote));
  const coverage = totalWeight > 0 ? assessedWeight / totalWeight : 0;
  let status = 'scored';
  let score = assessedWeight > 0 ? Math.round((earned / assessedWeight) * 100) : null;
  const noCriteria = totalWeight === 0;
  if (noCriteria || coverage < COVERAGE_FLOOR) status = 'insufficient_data';
  let recommendation;
  if (status === 'insufficient_data') { recommendation = 'Consider'; } else { recommendation = score >= T_ADVANCE ? 'Hire' : score >= T_CONSIDER ? 'Consider' : 'Reject'; }
  const knockout = requiredMissing.length > 0;
  if (knockout || flags.length || integrity.length) { if (status !== 'insufficient_data') status = 'manual_review'; if (recommendation === 'Hire') recommendation = 'Consider'; }
  let finalHr = txt(a.fit_for_role);
  let summary = txt(a.summary);
  const notes = [];
  if (requiredMissing.length) notes.push('Required criteria not evidenced (' + requiredMissing.join(', ') + ') -- screen-out for human confirmation.');
  if (flags.length) notes.push('Knockout flags: ' + flags.join(', ') + '.');
  if (integrity.length) notes.push('Integrity concern (' + integrity.map((c) => txt(c.concern)).join('; ') + ') -- mandatory human review.');
  if (status === 'insufficient_data') notes.push(noCriteria ? 'No employer criteria provided -- human review.' : 'Too few criteria could be assessed -- human review.');
  if (notes.length) { const n = 'NOTE: ' + notes.join(' '); finalHr = finalHr ? (finalHr + '\n\n' + n) : n; summary = summary ? (summary + '\n\n' + n) : n; }
  out.push({ json: { overall_score: score, recommendation, strengths: toArray(a.strengths), weaknesses: toArray(a.weaknesses), red_flags: [...flags, ...integrity.map((c) => txt(c.concern))], summary, fit_for_role: txt(a.fit_for_role), final_hr_evaluation: finalHr, status, screening_coverage: Math.round(coverage * 100) / 100, criteria_results: criteriaResults, knockout_flags: flags, required_missing: requiredMissing, integrity_concerns: integrity } });
}
return out;
